using System.Text.Json.Serialization;
using CounterStrikeSharp.API.Core;

namespace TheatreScreen;

/// <summary>
/// Plugin config, auto-generated by CounterStrikeSharp at
/// <c>configs/plugins/TheatreScreen/TheatreScreen.json</c> on first load.
///
/// The screen is placed by its bottom edge: two floor points taken from <c>getpos</c>,
/// named from the audience's point of view. Defaults are the spot picked on the test
/// map, snapped to a wall facing +Y (yaw 90) — the audience stands at larger Y looking
/// back toward -Y, so their left is +X.
/// </summary>
public sealed class TheatreScreenConfig : BasePluginConfig
{
    /// <summary>Bottom-left corner as the audience sees it (x, y, z).</summary>
    [JsonPropertyName("BottomLeft")] public float[] BottomLeft { get; set; } = [1023.92f, -2465.0f, -176.0f];

    /// <summary>Bottom-right corner as the audience sees it (x, y, z).</summary>
    [JsonPropertyName("BottomRight")] public float[] BottomRight { get; set; } = [860.16f, -2465.0f, -176.0f];

    /// <summary>Direction the screen faces (toward the audience). Only orients
    /// point_worldtext pixels; beams face the camera on their own.</summary>
    [JsonPropertyName("FacingYaw")] public float FacingYaw { get; set; } = 90f;

    /// <summary>Lift the bottom edge off the floor by this many units.</summary>
    [JsonPropertyName("Elevation")] public float Elevation { get; set; } = 24f;

    /// <summary>Resolution. Pixels are square, so height = width * Rows / Columns.</summary>
    [JsonPropertyName("Columns")] public int Columns { get; set; } = 96;
    [JsonPropertyName("Rows")] public int Rows { get; set; } = 54;

    /// <summary>Feeder base URL reachable from the game container; !play supplies the video URL.</summary>
    [JsonPropertyName("FeederUrl")] public string FeederUrl { get; set; } = "http://172.30.0.1:8787";
    [JsonPropertyName("FramesPerSecond")] public int FramesPerSecond { get; set; } = 15;

    /// <summary>Black wall behind the pixels, overhanging by <see cref="Bezel"/> units.
    /// Beams are additive, so without it they look like tinted glass.</summary>
    [JsonPropertyName("Backdrop")] public bool Backdrop { get; set; } = true;
    [JsonPropertyName("Bezel")] public float Bezel { get; set; } = 4f;

    /// <summary>Pixel primitive: "beam" or "text". See docs in ScreenPixels.cs.</summary>
    [JsonPropertyName("PixelType")] public string PixelType { get; set; } = "beam";

    /// <summary>Glyph drawn by each "text" pixel, and a fudge factor on its size since
    /// the glyph's real extent depends on the font.</summary>
    [JsonPropertyName("TextGlyph")] public string TextGlyph { get; set; } = "█";
    [JsonPropertyName("TextScale")] public float TextScale { get; set; } = 1.0f;
}
